SELECT category, SUM(amount) AS totalAmount
FROM transactions
WHERE DATE_FORMAT(transaction_date, '%Y-%m') = #{yearMonth}
AND type = #{type}
GROUP BY category
ORDER BY totalAmount DESC

SELECT IFNULL(SUM(amount), 0)
FROM transactions
WHERE DATE_FORMAT(transaction_date, '%Y-%m') = #{yearMonth}
AND type = #{type}
